import { Component } from '@angular/core';
import { FormControl } from '@angular/forms';
import { Router } from '@angular/router';
import { debounceTime, distinctUntilChanged, switchMap, catchError } from 'rxjs/operators';
import { of, EMPTY } from 'rxjs';
import { CompasService } from '../../core/services/compas.service';
import { Compa } from '../../shared/models/compa.model';

@Component({
  selector: 'app-home',
  templateUrl: './home.component.html',
  styleUrls: ['./home.component.scss']
})
export class HomeComponent {
  searchCtrl = new FormControl('');
  results: Compa[] = [];
  loading = false;
  searched = false;
  error = '';

  constructor(private compasService: CompasService, private router: Router) {
    this.searchCtrl.valueChanges.pipe(
      debounceTime(400),
      distinctUntilChanged(),
      switchMap((q: any) => {
        if (!q || q.trim().length < 2) {
          this.results  = [];
          this.searched = false;
          this.loading  = false;
          return EMPTY;
        }
        this.loading = true;
        this.error   = '';
        return this.compasService.search(q.trim()).pipe(
          catchError(() => {
            this.error   = 'Error al buscar. Intenta de nuevo.';
            this.loading = false;
            return of([] as Compa[]);
          })
        );
      })
    ).subscribe((data: Compa[]) => {
      this.results  = data;
      this.searched = true;
      this.loading  = false;
    });
  }

  go(id: number): void {
    this.router.navigate(['/compa', id]);
  }
}
<section class="hero">
  <div class="hero-content">
    <h1>¡Busca y califica a tus compas!</h1>
    <p class="subtitle">Evalúa a tus compañeros de clase o trabajo, o revisa las calificaciones antes de elegir tu grupo.</p>

    <div class="search-box">
      <input
        type="text"
        [formControl]="searchCtrl"
        placeholder="Escribe un nombre o apellido..."
        class="search-input"
        autocomplete="off"
      />
      <button class="search-btn" type="button">
        <svg xmlns="http://www.w3.org/2000/svg" width="18" height="18" viewBox="0 0 24 24" fill="none"
          stroke="currentColor" stroke-width="2.5" stroke-linecap="round" stroke-linejoin="round">
          <circle cx="11" cy="11" r="8"/><line x1="21" y1="21" x2="16.65" y2="16.65"/>
        </svg>
        Buscar
      </button>
      <span class="spinner-inline" *ngIf="loading"></span>
    </div>

    <a routerLink="/register" class="hero-link">¿Eres nuevo? Registra a un compañero →</a>
  </div>
</section>

<div class="container results-area" *ngIf="searched">
  <div class="alert alert-error" *ngIf="error">{{ error }}</div>

  <p class="results-count" *ngIf="!error">
    {{ results.length }} resultado{{ results.length !== 1 ? 's' : '' }} encontrado{{ results.length !== 1 ? 's' : '' }}
  </p>

  <div class="results-grid" *ngIf="results.length > 0">
    <div class="compa-card" *ngFor="let c of results" (click)="go(c.id)">
      <div class="avatar" [style.background]="'hsl(' + (c.id * 57) + ',55%,55%)'">
        <img *ngIf="c.foto_url" [src]="c.foto_url" [alt]="c.nombre">
        <span *ngIf="!c.foto_url">{{ c.nombre[0] }}{{ c.apellido[0] }}</span>
      </div>
      <div class="card-body">
        <h3>{{ c.nombre }} {{ c.apellido }}</h3>
        <app-star-rating [value]="c.promedio ?? 0" [readonly]="true" size="sm"></app-star-rating>
        <p class="meta">
          <span *ngIf="c.promedio; else sinCalif">{{ c.promedio | number:'1.1-1' }} / 5</span>
          <ng-template #sinCalif><span class="no-rating">Sin calificar</span></ng-template>
          &nbsp;·&nbsp; {{ c.total_calificaciones }} reseña{{ c.total_calificaciones !== 1 ? 's' : '' }}
        </p>
      </div>
      <span class="arrow">›</span>
    </div>
  </div>

  <div class="empty" *ngIf="results.length === 0 && !error">
    <div class="empty-icon">🔎</div>
    <p>No encontramos compas con ese nombre.</p>
  </div>
</div>

<section class="how-it-works" *ngIf="!searched">
  <div class="container">
    <h2>¿Cómo funciona?</h2>
    <div class="steps">
      <div class="step">
        <div class="step-icon-wrap">
          <span class="step-icon">🔍</span>
        </div>
        <h3>Busca</h3>
        <p>Encuentra a tu compa por nombre o apellido en nuestra base de datos</p>
      </div>
      <div class="step">
        <div class="step-icon-wrap">
          <span class="step-icon">⭐</span>
        </div>
        <h3>Califica</h3>
        <p>Deja tu puntuación honesta y un comentario sobre tu experiencia</p>
      </div>
      <div class="step">
        <div class="step-icon-wrap">
          <span class="step-icon">🤝</span>
        </div>
        <h3>Conecta</h3>
        <p>Consulta reseñas antes de elegir compañero de grupo o trabajo</p>
      </div>
    </div>
  </div>
</section>
